        private void SetUpReadTimer()
        {
            _readTimer ??= new DispatcherTimer()
            {
                Interval = TimeSpan.FromSeconds(3)
            };

            _readTimer.Tick += async (s, e) =>
            {
                await MyWebView?.ExecuteScriptAsync("getContent()");
            };
            _readTimer.Start();
        }

        private static string GetLogsDirectory()
        {
            var localStatePath = ApplicationData.Current.LocalFolder.Path;
            return Path.Combine(localStatePath, "Logs");
        }

        private void SetupUiFreezeDetection()
        {
            _lastUiHeartbeat = DateTime.UtcNow;

            // UI thread heartbeat - updates timestamp every 500ms
            _uiFreezeTimer = DispatcherQueue.GetForCurrentThread().CreateTimer();
            _uiFreezeTimer.Interval = TimeSpan.FromMilliseconds(500);
            _uiFreezeTimer.Tick += (s, e) =>
            {
                _lastUiHeartbeat = DateTime.UtcNow;
            };
            _uiFreezeTimer.Start();

            // Background watchdog - checks if UI thread is responsive
            _backgroundWatchdog = new Timer(_ =>
            {
                var elapsed = (DateTime.UtcNow - _lastUiHeartbeat).TotalMilliseconds;
                if (elapsed > FreezeThresholdMs)
                {
                    LogAction($"[UI FREEZE DETECTED] UI thread is unresponsive");
                }
            }, null, 1000, 500);

            Debug.WriteLine("[SETUP] UI freeze detection initialized");
        }

        private void LogAction(string message)
        {
            string logEntry = $"[{DateTime.Now:yyyy-MM-dd HH:mm:ss.fff}] {message}";

            try
            {
                //Directory.CreateDirectory(Path.GetDirectoryName(_actionLogFile)!);
                File.AppendAllText(_actionLogFile, logEntry + Environment.NewLine);
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"Failed to write to log file: {ex.Message}");
            }
        }

        private string SetupUserProfile()
        {
            try
            {
                var localStatePath = ApplicationData.Current.LocalFolder.Path;
                string userProfilePath = Path.Combine(localStatePath, "WebView2Profile");

                if (!Directory.Exists(userProfilePath))
                {
                    Directory.CreateDirectory(userProfilePath);
                    LogAction($"Created user profile directory: {userProfilePath}");
                }

                string profileConfigPath = Path.Combine(userProfilePath, "profile.json");
                if (!File.Exists(profileConfigPath))
                {
                    string profileConfig = @"{
  ""profile_name"": """ + Environment.UserName + @""",
  ""created_date"": """ + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") + @""",
  ""cache_size_mb"": 100,
  ""enable_cookies"": true,
  ""enable_local_storage"": true,
  ""enable_indexeddb"": true
}";
                    File.WriteAllText(profileConfigPath, profileConfig);
                    LogAction("Profile configuration created");
                }

                string[] subDirs = { "Cache", "Cookies", "LocalStorage", "IndexedDB", "WebSQL" };
                foreach (var subDir in subDirs)
                {
                    string subPath = Path.Combine(userProfilePath, subDir);
                    if (!Directory.Exists(subPath))
                    {
                        Directory.CreateDirectory(subPath);
                    }
                }

                LogAction($"User profile setup complete at: {userProfilePath}");
                return userProfilePath;
            }
            catch (Exception ex)
            {
                LogAction($"ERROR: Failed to setup user profile - {ex.Message}");

                string fallbackPath = Path.Combine(Path.GetTempPath(), "WInUI3_POC_WebView2");
                Directory.CreateDirectory(fallbackPath);
                LogAction($"Using fallback profile path: {fallbackPath}");

                return fallbackPath;
            }
        }
        private async void InitializeWebView()
        {
            try
